let phase='watch';
function step(ctx){
 if(phase==='done') return {};
 const swarm=ctx.game.building({id:0,generation:1});
 if(!swarm){phase='done';ctx.wakeAgent({key:'workforce-swarm-missing',reason:'The designated swarm is no longer available; the workforce order needs attention.',data:{tick:ctx.tick}});return {};}
 if(phase==='verify'){
  const confirmed=swarm.production[0]===0 && swarm.production[1]===0 && swarm.production[2]>0;
  phase='done';
  ctx.wakeAgent({key:'sixteen-workers-production-result',reason:confirmed?'Confirmed: the sixteen-worker threshold was reached and our swarm now produces only warriors.':'The warrior-only production order was issued but has not been confirmed.',data:{tick:ctx.tick,confirmed,production:swarm.production}});
  return {output:{confirmed}};
 }
 let workers=0;
 for(let offset=0;offset<32768;offset+=200){
  const page=ctx.game.units({team:ctx.myTeam,offset,limit:200});
  workers+=page.filter(u=>u.type===0).length;
  if(workers>=16 || page.length<200) break;
 }
 if(workers<16) return {output:{workers}};
 phase='verify';
 return {output:{workers,productionOrderIssued:true},orders:[{type:'production',building:{id:swarm.id,generation:swarm.generation},ratios:[0,0,1]}]};
}
